import { Box, Button } from '@mui/material';
import Link from 'next/link';
import { useTranslation } from 'react-i18next';

export function AndroidFloatWindowLink() {
  const { t } = useTranslation('homepage/components/android-float/window/content');
  return (
    <Box sx={{mt:1, mb:1}}>
      <Button component={Link} href="/android-float-window" variant="contained" color="primary">
         {t('AndroidFloatWindowLink.name')}
      </Button>
    </Box>
  );
}
