import { AndroidPermission } from "@droid/android";
import { toProxy } from "@fanfanlo";
import { AndroidPermissionsButton } from "./AndroidPermissionsButton";

interface IPermissionsProps {
  permissions: AndroidPermission[];
}

interface AndroidPermissionsButtonProps {
  permissionsProps: IPermissionsProps; // 权限数据对象
}

export function TestAndroidePermissionsButton(){
    const data = toProxy({permissions:[]})
    return (
        <AndroidPermissionsButton permissionsProps={data} />
    )
}