// useTranslation 导入规则，使用 @fanfanlo 库里的 useTranslation
import { useTranslation } from '@fanfanlo';

// 命名规则，每个组件都跟随一个与自己同名的 i18n.json 文件，例如这个是 ExampleButton.json
export function ExampleButton() {
    // 命名空间规则
    // homepage 是当前项目的名称
    // components/i18n-exmaples/button/ 是从项目名称 homepage开始，到当前目录的路径去掉了src
    // content是固定字段。
  const { t } = useTranslation('homepage/components/i18n-exmaples/button/content');
  return (
    <>
    {/* 使用时需要加上自己的文件名 ExampleButton */}
      <button>{t('ExampleButton.name')}</button>
    </>
  );
}

